// Pong Neon: você (esquerda) contra a máquina (direita)
const tela = document.getElementById('tela');
const ctx = tela.getContext('2d');
const L = tela.width, A = tela.height;
const RAQ = { l: 12, a: 90 }, VITORIA = 7;
const voce = { x: 24, y: A / 2 - 45, pts: 0 }, cpu = { x: L - 36, y: A / 2 - 45, pts: 0 };
let bola, estado = 'inicio', teclas = {}, rastro = [], faiscas = [], tremor = 0;

const audio = new (window.AudioContext || window.webkitAudioContext)();
function bip(freq, dur = 0.06, tipo = 'square') {
  const o = audio.createOscillator(), g = audio.createGain();
  o.type = tipo; o.frequency.value = freq; g.gain.value = 0.06;
  g.gain.exponentialRampToValueAtTime(0.0001, audio.currentTime + dur);
  o.connect(g).connect(audio.destination); o.start(); o.stop(audio.currentTime + dur);
}

function novaBola(dir) {
  const ang = (Math.random() * 0.8 - 0.4);
  bola = { x: L / 2, y: A / 2, vx: Math.cos(ang) * 6 * dir, vy: Math.sin(ang) * 6, r: 8 };
  rastro = [];
}
novaBola(1);

addEventListener('keydown', e => {
  teclas[e.key.toLowerCase()] = true;
  if (e.code === 'Space') { e.preventDefault(); if (estado !== 'jogando') { if (estado === 'fim') { voce.pts = cpu.pts = 0; } estado = 'jogando'; novaBola(Math.random() < 0.5 ? 1 : -1); audio.resume(); } }
});
addEventListener('keyup', e => teclas[e.key.toLowerCase()] = false);
tela.addEventListener('pointermove', e => { const r = tela.getBoundingClientRect(); voce.y = (e.clientY - r.top) / r.height * A - RAQ.a / 2; });
tela.addEventListener('pointerdown', () => { audio.resume(); if (estado !== 'jogando') { if (estado === 'fim') voce.pts = cpu.pts = 0; estado = 'jogando'; novaBola(1); } });

function faisca(x, y, cor) { for (let i = 0; i < 14; i++) faiscas.push({ x, y, vx: (Math.random() - 0.5) * 8, vy: (Math.random() - 0.5) * 8, v: 1, cor }); }

function rebater(r, lado) {
  if (bola.y + bola.r < r.y || bola.y - bola.r > r.y + RAQ.a) return false;
  if (lado < 0 ? bola.x - bola.r > r.x + RAQ.l || bola.x < r.x : bola.x + bola.r < r.x || bola.x > r.x + RAQ.l) return false;
  const rel = (bola.y - (r.y + RAQ.a / 2)) / (RAQ.a / 2);
  const vel = Math.min(15, Math.hypot(bola.vx, bola.vy) * 1.06);
  const ang = rel * 1.0;
  bola.vx = Math.cos(ang) * vel * -lado; bola.vy = Math.sin(ang) * vel;
  bola.x = lado < 0 ? r.x + RAQ.l + bola.r : r.x - bola.r;
  faisca(bola.x, bola.y, lado < 0 ? '#22d3ee' : '#f472b6'); tremor = 6; bip(lado < 0 ? 520 : 380);
  return true;
}

function atualizar() {
  if (teclas['w'] || teclas['arrowup']) voce.y -= 8;
  if (teclas['s'] || teclas['arrowdown']) voce.y += 8;
  voce.y = Math.max(0, Math.min(A - RAQ.a, voce.y));
  if (estado !== 'jogando') return;
  // a máquina erra um pouco de propósito
  const alvo = bola.vx > 0 ? bola.y - RAQ.a / 2 + Math.sin(Date.now() / 300) * 18 : A / 2 - RAQ.a / 2;
  cpu.y += Math.max(-5.2, Math.min(5.2, alvo - cpu.y));
  cpu.y = Math.max(0, Math.min(A - RAQ.a, cpu.y));
  bola.x += bola.vx; bola.y += bola.vy;
  rastro.push({ x: bola.x, y: bola.y }); if (rastro.length > 14) rastro.shift();
  if (bola.y < bola.r || bola.y > A - bola.r) { bola.vy *= -1; bola.y = Math.max(bola.r, Math.min(A - bola.r, bola.y)); bip(220, 0.04); }
  rebater(voce, -1) || rebater(cpu, 1);
  if (bola.x < -20 || bola.x > L + 20) {
    const ponto = bola.x > L ? voce : cpu;
    ponto.pts++; bip(ponto === voce ? 880 : 140, 0.25, 'sawtooth'); tremor = 12;
    if (ponto.pts >= VITORIA) { estado = 'fim'; bip(ponto === voce ? 1040 : 110, 0.6, 'triangle'); }
    else novaBola(ponto === voce ? 1 : -1);
  }
}

function neon(cor, blur) { ctx.shadowColor = cor; ctx.shadowBlur = blur; ctx.fillStyle = cor; ctx.strokeStyle = cor; }
function desenhar() {
  ctx.save();
  if (tremor > 0) { ctx.translate((Math.random() - 0.5) * tremor, (Math.random() - 0.5) * tremor); tremor *= 0.85; if (tremor < 0.3) tremor = 0; }
  ctx.fillStyle = 'rgba(5, 4, 12, 0.45)'; ctx.fillRect(-20, -20, L + 40, A + 40);
  neon('#312e81', 0); ctx.setLineDash([10, 14]); ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(L / 2, 0); ctx.lineTo(L / 2, A); ctx.stroke(); ctx.setLineDash([]);
  ctx.font = 'bold 64px system-ui'; ctx.textAlign = 'center';
  neon('#22d3ee', 18); ctx.fillText(voce.pts, L / 2 - 80, 80);
  neon('#f472b6', 18); ctx.fillText(cpu.pts, L / 2 + 80, 80);
  neon('#22d3ee', 22); ctx.fillRect(voce.x, voce.y, RAQ.l, RAQ.a);
  neon('#f472b6', 22); ctx.fillRect(cpu.x, cpu.y, RAQ.l, RAQ.a);
  rastro.forEach((p, i) => { neon('#fde047', 10); ctx.globalAlpha = i / rastro.length * 0.5; ctx.beginPath(); ctx.arc(p.x, p.y, bola.r * i / rastro.length, 0, 7); ctx.fill(); });
  ctx.globalAlpha = 1;
  if (estado === 'jogando') { neon('#fde047', 24); ctx.beginPath(); ctx.arc(bola.x, bola.y, bola.r, 0, 7); ctx.fill(); }
  faiscas = faiscas.filter(f => (f.v -= 0.04) > 0);
  faiscas.forEach(f => { f.x += f.vx; f.y += f.vy; neon(f.cor, 12); ctx.globalAlpha = f.v; ctx.fillRect(f.x, f.y, 3, 3); });
  ctx.globalAlpha = 1;
  if (estado !== 'jogando') {
    neon('#e0e7ff', 16); ctx.font = 'bold 34px system-ui';
    const msg = estado === 'fim' ? (voce.pts > cpu.pts ? 'VOCÊ VENCEU! 🏆' : 'A MÁQUINA VENCEU') : 'PONG NEON';
    ctx.fillText(msg, L / 2, A / 2 - 10);
    ctx.font = '18px system-ui'; neon('#a5b4fc', 8); ctx.fillText('aperte Espaço (ou toque) para ' + (estado === 'fim' ? 'jogar de novo' : 'começar'), L / 2, A / 2 + 30);
  }
  ctx.restore();
}
(function loop() { atualizar(); desenhar(); requestAnimationFrame(loop); })();
